import { memo } from 'react';
import { useToast } from '../contexts/ToastContext';
import { X, Check, Info, AlertCircle, Copy } from 'lucide-react';

const MAX_TOASTS = 4;

function ToastItem({ toast, onRemove }: { toast: any; onRemove: (id: string) => void }) {
  const { type, message, id } = toast;

  const getStyles = () => {
    switch (type) {
      case 'success':
        return {
          icon: <Check size={16} className="text-emerald-400 shrink-0" />,
          border: 'border-emerald-500/30',
          bg: 'bg-emerald-500/10',
        };
      case 'error':
        return {
          icon: <AlertCircle size={16} className="text-red-400 shrink-0" />,
          border: 'border-red-500/30',
          bg: 'bg-red-500/10',
        };
      case 'warning':
        return {
          icon: <AlertCircle size={16} className="text-amber-400 shrink-0" />,
          border: 'border-amber-500/30',
          bg: 'bg-amber-500/10',
        };
      case 'copy':
        return {
          icon: <Copy size={16} className="text-blue-400 shrink-0" />,
          border: 'border-blue-500/30',
          bg: 'bg-blue-500/10',
        };
      default:
        return {
          icon: <Info size={16} className="text-blue-400 shrink-0" />,
          border: 'border-blue-500/30',
          bg: 'bg-blue-500/10',
        };
    }
  };

  const styles = getStyles();

  return (
    <div
      className={`flex items-start gap-2.5 bg-[#1a1a2e]/95 backdrop-blur-md ${styles.border} border rounded-xl px-3.5 py-2.5 shadow-2xl pointer-events-auto transition-all duration-300 ${styles.bg}`}
      role="alert"
    >
      {styles.icon}
      <p className="text-white text-xs sm:text-sm flex-1 leading-relaxed">{message}</p>
      <button
        onClick={() => onRemove(id)}
        className="text-white/30 hover:text-white/60 transition-colors p-0.5 shrink-0"
        aria-label="Dismiss notification"
      >
        <X size={12} />
      </button>
    </div>
  );
}

function ToastContainerInner() {
  const { toasts, removeToast } = useToast();

  return (
    <div
      className="fixed bottom-4 right-4 z-[9999] flex flex-col gap-2 max-w-sm pointer-events-auto"
      role="region"
      aria-label="Notifications"
      aria-live="polite"
    >
      {toasts.slice(-MAX_TOASTS).map(toast => (
        <ToastItem key={toast.id} toast={toast} onRemove={removeToast} />
      ))}
    </div>
  );
}

export default memo(ToastContainerInner);