import { createContext, useContext, useState, useCallback, useMemo, ReactNode } from 'react';

export interface UserSettings {
  defaultStreamSource: string;
  autoPlayNextEpisode: boolean;
  videoQuality: string;
  playbackSpeed: number;
  showTitles: boolean;
  reducedMotion: boolean;
  compactMode: boolean;
}

const DEFAULT_SETTINGS: UserSettings = {
  defaultStreamSource: 'auto',
  autoPlayNextEpisode: true,
  videoQuality: 'auto',
  playbackSpeed: 1,
  showTitles: true,
  reducedMotion: false,
  compactMode: false,
};

const STORAGE_KEY = 'stinkflix-settings';

interface SettingsContextType {
  settings: UserSettings;
  updateSetting: <K extends keyof UserSettings>(key: K, value: UserSettings[K]) => void;
  updateSettings: (updates: Partial<UserSettings>) => void;
  resetSettings: () => void;
  isDirty: boolean;
}

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (typeof parsed === 'object' && parsed !== null) {
          return { ...DEFAULT_SETTINGS, ...parsed };
        }
      }
    } catch {
      // localStorage corrupted, use defaults
    }
    return DEFAULT_SETTINGS;
  });

  const isDirty = useMemo(() => {
    return JSON.stringify(settings) !== JSON.stringify(DEFAULT_SETTINGS);
  }, [settings]);

  const updateSetting = useCallback(<K extends keyof UserSettings>(key: K, value: UserSettings[K]) => {
    setSettings(prev => {
      const next = { ...prev, [key]: value };
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch {
        // localStorage full or unavailable
      }
      return next;
    });
  }, []);

  const updateSettings = useCallback((updates: Partial<UserSettings>) => {
    setSettings(prev => {
      const next = { ...prev, ...updates };
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch {
        // localStorage full or unavailable
      }
      return next;
    });
  }, []);

  const resetSettings = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      // localStorage unavailable
    }
  }, []);

  const value = useMemo(() => ({
    settings,
    updateSetting,
    updateSettings,
    resetSettings,
    isDirty,
  }), [settings, updateSetting, updateSettings, resetSettings, isDirty]);

  return (
    <SettingsContext.Provider value={value}>
      {children}
    </SettingsContext.Provider>
  );
}

export function useSettings() {
  const context = useContext(SettingsContext);
  if (!context) throw new Error('useSettings must be used within SettingsProvider');
  return context;
}