import { useState, useEffect, useRef, useCallback, useMemo, memo } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Search, Film, ChevronDown, User, Shuffle, Settings, LogOut } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useDebounce } from '../lib/hooks';
import { searchMulti, img, type MediaItem } from '../lib/tmdb';

// Memoized search result item to prevent re-renders
const SearchResultItem = memo(function SearchResultItem({ item, onClick }: { item: MediaItem; onClick: () => void }) {
  const title = item.title || item.name || '';
  const poster = img(item.poster_path, 'w92');
  const year = (item.release_date || item.first_air_date || '').slice(0, 4);

  return (
    <button
      onClick={onClick}
      className="w-full flex items-center gap-3 px-3 py-2 hover:bg-white/10 transition-colors text-left"
    >
      {poster ? (
        <img
          src={poster}
          alt=""
          className="w-8 h-12 object-cover rounded"
          loading="lazy"
          onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
        />
      ) : (
        <div className="w-8 h-12 rounded bg-white/5 flex items-center justify-center">
          <Film size={12} className="text-white/20" />
        </div>
      )}
      <div className="flex-1 min-w-0">
        <p className="text-white text-sm font-medium truncate">{title}</p>
        <p className="text-white/40 text-xs">{item.media_type || 'movie'}{year ? ` · ${year}` : ''}</p>
      </div>
    </button>
  );
});

// Memoized nav link to reduce re-renders on navigation
const NavLink = memo(function NavLink({ to, icon, label }: { to: string; icon: React.ReactNode; label: string }) {
  const location = useLocation();
  const active = location.pathname === to || (to !== '/' && location.pathname.startsWith(to));
  return (
    <Link
      to={to}
      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${
        active
          ? 'text-emerald-400 bg-emerald-400/10'
          : 'text-white/70 hover:text-white hover:bg-white/10'
      }`}
      role="menuitem"
    >
      {icon}
      {label}
    </Link>
  );
});

// Memoized mobile nav link
const MobileNavLink = memo(function MobileNavLink({ to, icon, label }: { to: string; icon: React.ReactNode; label: string }) {
  const location = useLocation();
  const active = location.pathname === to || (to !== '/' && location.pathname.startsWith(to));
  return (
    <Link
      to={to}
      className={`flex items-center gap-2 px-4 py-3 text-sm font-medium transition-colors ${
        active
          ? 'text-emerald-400 bg-emerald-400/10'
          : 'text-white/70 hover:text-white hover:bg-white/10'
      }`}
    >
      {icon}
      {label}
    </Link>
  );
});

// Memoized mobile menu
function MobileMenuInner() {
  const [open, setOpen] = useState(false);
  const location = useLocation();

  useEffect(() => setOpen(false), [location.pathname]);

  return (
    <div className="md:hidden relative">
      <button
        onClick={() => setOpen(o => !o)}
        className="p-2 text-white/70 hover:text-white hover:bg-white/10 rounded-full transition-all"
        aria-label="Mobile menu"
        aria-expanded={open}
      >
        <ChevronDown size={18} className={`transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <div className="absolute top-full right-0 mt-2 w-48 bg-[#1a1a2e]/98 backdrop-blur-xl border border-white/10 rounded-xl shadow-xl overflow-hidden">
          <MobileNavLink to="/" icon={<Film size={15} />} label="Home" />
          <MobileNavLink to="/watchlist" icon={<Settings size={15} />} label="Watchlist" />
        </div>
      )}
    </div>
  );
}

export default memo(function Navbar() {
  const { isAuthenticated, username, logout } = useAuth();
  const [scrolled, setScrolled] = useState(false);
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounce(query, 300);
  const [showSearch, setShowSearch] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const location = useLocation();

  // Fetch search results with O(1) dedup using Set
  useEffect(() => {
    if (!debouncedQuery || debouncedQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    setIsSearching(true);
    searchMulti(debouncedQuery).then((res: { results?: MediaItem[] }) => {
      // Dedup by ID for O(1) lookups
      const seen = new Set<number>();
      const unique: MediaItem[] = [];
      for (const item of (res.results || [])) {
        if (!seen.has(item.id)) {
          seen.add(item.id);
          unique.push(item);
        }
      }
      setSearchResults(unique.slice(0, 8));
      setIsSearching(false);
    }).catch(() => {
      setIsSearching(false);
    });
  }, [debouncedQuery]);

  // Click outside handlers (batched)
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as Node;
      if (profileRef.current && !profileRef.current.contains(target)) {
        setShowProfile(false);
      }
      if (searchRef.current && !searchRef.current.contains(target)) {
        setShowSearch(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setShowSearch(true);
      }
      if (e.key === 'Escape') {
        setShowSearch(false);
        setShowProfile(false);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  const surpriseMe = useCallback(() => {
    const types = ['movie', 'tv'] as const;
    const type = types[Math.floor(Math.random() * types.length)];
    const randomId = Math.floor(Math.random() * 15000) + 1;
    navigate(`/${type}/${randomId}`);
  }, [navigate]);

  // Scroll listener with passive flag
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Clear search on navigation
  useEffect(() => {
    setShowSearch(false);
    setQuery('');
    setSearchResults([]);
  }, [location.pathname]);

  const handleSearch = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/search?q=${encodeURIComponent(query.trim())}`);
    }
  }, [query, navigate]);

  const handleResultClick = useCallback((item: MediaItem) => {
    const type = item.media_type === 'tv' ? 'tv' : 'movie';
    navigate(`/${type}/${item.id}`);
    setShowSearch(false);
    setQuery('');
  }, [navigate]);

  // Memoized nav links
  const navLinks = useMemo(() => [
    { to: '/', icon: <Film size={15} />, label: 'Home' },
    { to: '/watchlist', icon: <Settings size={15} />, label: 'Watchlist' },
  ], []);

  // Memoized profile items
  const profileItems = useMemo(() => [
    { icon: <Settings size={14} />, label: 'Settings', action: () => navigate('/settings') },
    { icon: <LogOut size={14} />, label: 'Sign out', action: () => { logout(); navigate('/'); }, danger: true },
  ], [navigate, logout]);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 will-change-transform ${
        scrolled ? 'bg-[#0a0a0f]/95 backdrop-blur-md shadow-xl shadow-black/20' : 'bg-gradient-to-b from-black/70 to-transparent'
      }`}
      role="navigation"
      aria-label="Main navigation"
      style={{ contain: 'style layout' }}
    >
      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 h-16 flex items-center justify-between gap-4">
        {/* Logo */}
        <Link to="/" className="flex items-center gap-2 shrink-0 group" aria-label="StinkFlix Home">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-emerald-500 to-blue-600 flex items-center justify-center shadow-lg shadow-emerald-500/25 group-hover:shadow-emerald-500/50 transition-all">
            <Film size={16} className="text-white" />
          </div>
          <span className="text-white font-bold text-lg tracking-tight">
            Stink<span className="text-emerald-400">Flix</span>
          </span>
        </Link>

        {/* Nav Links */}
        <div className="hidden md:flex items-center gap-1" role="menubar">
          {navLinks.map(link => (
            <NavLink key={link.to} {...link} />
          ))}
        </div>

        {/* Search */}
        <div className="flex items-center gap-2 ml-auto relative" ref={searchRef}>
          {showSearch ? (
            <form onSubmit={handleSearch} className="flex items-center relative">
              <Search size={14} className="absolute left-3 text-white/40" />
              <input
                autoFocus
                type="text"
                value={query}
                onChange={e => setQuery(e.target.value)}
                placeholder="Search movies, shows..."
                className="bg-white/10 backdrop-blur border border-white/20 text-white placeholder-white/50 rounded-full pl-9 pr-8 py-1.5 text-sm w-52 sm:w-72 focus:outline-none focus:border-emerald-400/60 focus:bg-white/15 transition-all"
                aria-label="Search movies and TV shows"
                aria-autocomplete="list"
              />
              {isSearching && (
                <div className="absolute right-3">
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white/80 rounded-full animate-spin" />
                </div>
              )}
              {/* Search Results Dropdown */}
              {searchResults.length > 0 && (
                <div className="absolute top-full right-0 mt-2 w-80 max-h-96 overflow-y-auto bg-[#1a1a2e]/98 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl overflow-hidden" role="listbox">
                  {searchResults.map(item => (
                    <SearchResultItem
                      key={item.id}
                      item={item}
                      onClick={() => handleResultClick(item)}
                    />
                  ))}
                </div>
              )}
            </form>
          ) : (
            <>
              <button
                onClick={surpriseMe}
                className="p-2 text-white/70 hover:text-white hover:bg-white/10 rounded-full transition-all"
                title="Surprise Me"
                aria-label="Surprise me with a random title"
              >
                <Shuffle size={18} />
              </button>
              <button
                onClick={() => setShowSearch(true)}
                className="p-2 text-white/70 hover:text-white hover:bg-white/10 rounded-full transition-all hidden sm:flex"
                title="Search (⌘K)"
                aria-label="Search (keyboard shortcut: Cmd+K)"
              >
                <Search size={18} />
              </button>
              <kbd className="hidden sm:flex items-center gap-1 px-2 py-1 text-xs text-white/30 bg-white/5 rounded border border-white/10">⌘K</kbd>
            </>
          )}

          {/* Profile */}
          <div ref={profileRef} className="relative">
            <button
              onClick={() => setShowProfile(!showProfile)}
              className="flex items-center gap-1 p-1.5 rounded-full hover:bg-white/10 transition-colors"
              aria-label="User menu"
              aria-expanded={showProfile}
            >
              <div className="w-7 h-7 rounded-full bg-gradient-to-br from-emerald-500 to-blue-600 flex items-center justify-center">
                <User size={14} className="text-white" />
              </div>
              <ChevronDown size={14} className="text-white/50" />
            </button>

            {showProfile && (
              <div className="absolute right-0 top-full mt-2 w-64 bg-[#1a1a2e]/98 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl overflow-hidden" role="menu">
                <div className="p-3 border-b border-white/10">
                  <p className="text-white font-medium text-sm">{username || 'Guest'}</p>
                  <p className="text-white/40 text-xs">Member</p>
                </div>
                <div className="p-1">
                  {profileItems.map((item, i) => (
                    item.danger ? (
                      <button
                        key={i}
                        onClick={item.action}
                        className="w-full flex items-center gap-3 px-3 py-2 text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg text-sm transition-colors"
                        role="menuitem"
                      >
                        {item.icon}
                        {item.label}
                      </button>
                    ) : (
                      <button
                        key={i}
                        onClick={item.action}
                        className="w-full flex items-center gap-3 px-3 py-2 text-white/70 hover:text-white hover:bg-white/10 rounded-lg text-sm transition-colors"
                        role="menuitem"
                      >
                        {item.icon}
                        {item.label}
                      </button>
                    )
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Mobile menu */}
        <MobileMenuInner />
      </div>
    </nav>
  );
});