import { createContext, useContext, useState, useCallback, useMemo, ReactNode } from 'react';

export interface HistoryItem {
  id: number;
  type: 'movie' | 'tv';
  title: string;
  poster_path: string | null;
  timestamp: number;
  episode?: number;
  season?: number;
}

const HISTORY_KEY = 'stinkflix-history';
const MAX_HISTORY = 100;

interface HistoryContextType {
  history: HistoryItem[];
  addToHistory: (item: Omit<HistoryItem, 'timestamp'>) => void;
  addToHistoryBatch: (items: Omit<HistoryItem, 'timestamp'>[]) => void;
  removeFromHistory: (id: number, type?: 'movie' | 'tv') => void;
  clearHistory: () => void;
  getRecentViews: (limit?: number) => HistoryItem[];
  isInHistory: (id: number, type?: 'movie' | 'tv') => boolean;
  getHistoryKey: (id: number, type: 'movie' | 'tv') => string;
  historyCount: number;
}

const HistoryContext = createContext<HistoryContextType | undefined>(undefined);

export function HistoryProvider({ children }: { children: ReactNode }) {
  const [history, setHistory] = useState<HistoryItem[]>(() => {
    try {
      const stored = localStorage.getItem(HISTORY_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {
      // localStorage corrupted
    }
    return [];
  });

  const historyCount = history.length;

  const getHistoryKey = useCallback((id: number, type: 'movie' | 'tv') => {
    return `${id}-${type}`;
  }, []);

  const persistHistory = useCallback((items: HistoryItem[]) => {
    try {
      localStorage.setItem(HISTORY_KEY, JSON.stringify(items));
    } catch {
      // localStorage full or unavailable
    }
  }, []);

  const addToHistory = useCallback((item: Omit<HistoryItem, 'timestamp'>) => {
    setHistory(prev => {
      const filtered = prev.filter(h => !(h.id === item.id && h.type === item.type));
      const newItem: HistoryItem = { ...item, timestamp: Date.now() };
      const next = [newItem, ...filtered].slice(0, MAX_HISTORY);
      persistHistory(next);
      return next;
    });
  }, [persistHistory]);

  const addToHistoryBatch = useCallback((items: Omit<HistoryItem, 'timestamp'>[]) => {
    setHistory(prev => {
      const existingIds = new Set(prev.map(h => `${h.id}-${h.type}`));
      const newItems: HistoryItem[] = items
        .filter(item => !existingIds.has(`${item.id}-${item.type}`))
        .map(item => ({ ...item, timestamp: Date.now() }));
      const next = [...newItems, ...prev].slice(0, MAX_HISTORY);
      persistHistory(next);
      return next;
    });
  }, [persistHistory]);

  const removeFromHistory = useCallback((id: number, type?: 'movie' | 'tv') => {
    setHistory(prev => {
      const next = type
        ? prev.filter(h => !(h.id === id && h.type === type))
        : prev.filter(h => h.id !== id);
      persistHistory(next);
      return next;
    });
  }, [persistHistory]);

  const clearHistory = useCallback(() => {
    setHistory([]);
    try {
      localStorage.removeItem(HISTORY_KEY);
    } catch {
      // localStorage unavailable
    }
  }, []);

  const getRecentViews = useCallback((limit = 10) => {
    return history.slice(0, limit);
  }, [history]);

  const isInHistory = useCallback((id: number, type?: 'movie' | 'tv') => {
    return type
      ? history.some(h => h.id === id && h.type === type)
      : history.some(h => h.id === id);
  }, [history]);

  const value = useMemo(() => ({
    history,
    addToHistory,
    addToHistoryBatch,
    removeFromHistory,
    clearHistory,
    getRecentViews,
    isInHistory,
    getHistoryKey,
    historyCount,
  }), [history, addToHistory, addToHistoryBatch, removeFromHistory, clearHistory, getRecentViews, isInHistory, getHistoryKey, historyCount]);

  return (
    <HistoryContext.Provider value={value}>
      {children}
    </HistoryContext.Provider>
  );
}

export function useHistory() {
  const context = useContext(HistoryContext);
  if (!context) throw new Error('useHistory must be used within HistoryProvider');
  return context;
}