import { createContext, useContext, useState, useCallback, useMemo, ReactNode, useRef } from 'react';
import { X, Check, Info, AlertCircle, Copy } from 'lucide-react';

export type ToastType = 'success' | 'error' | 'info' | 'copy' | 'warning';

export interface Toast {
  id: string;
  message: string;
  type: ToastType;
  duration?: number;
  action?: { label: string; onClick: () => void };
}

interface ToastContextType {
  toasts: Toast[];
  addToast: (message: string, type?: ToastType, duration?: number, action?: Toast['action']) => void;
  removeToast: (id: string) => void;
  clearToasts: () => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);
const MAX_TOASTS = 4;
const DEFAULT_DURATION = 3500;

// Memoized style maps to avoid regenerating on every render
const ICON_MAP: Record<ToastType, React.ReactNode> = {
  success: <Check size={18} className="text-emerald-400 shrink-0" />,
  error: <AlertCircle size={18} className="text-red-400 shrink-0" />,
  warning: <AlertCircle size={18} className="text-amber-400 shrink-0" />,
  copy: <Copy size={18} className="text-blue-400 shrink-0" />,
  info: <Info size={18} className="text-blue-400 shrink-0" />,
};

const BORDER_MAP: Record<ToastType, string> = {
  success: 'border-emerald-500/30',
  error: 'border-red-500/30',
  warning: 'border-amber-500/30',
  copy: 'border-blue-500/30',
  info: 'border-blue-500/30',
};

const BG_MAP: Record<ToastType, string> = {
  success: 'bg-emerald-500/10',
  error: 'bg-red-500/10',
  warning: 'bg-amber-500/10',
  copy: 'bg-blue-500/10',
  info: 'bg-blue-500/10',
};

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const timeoutsRef = useRef<Map<string, number>>(new Map());

  const addToast = useCallback((message: string, type: ToastType = 'info', duration = DEFAULT_DURATION, action?: Toast['action']) => {
    const id = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
    const toast: Toast = { id, message, type, duration, action };

    setToasts(prev => {
      const next = [...prev, toast];
      return next.length > MAX_TOASTS ? next.slice(-MAX_TOASTS) : next;
    });

    if (duration && duration > 0) {
      const timeout = window.setTimeout(() => {
        setToasts(prev => prev.filter(t => t.id !== id));
        timeoutsRef.current.delete(id);
      }, duration);
      timeoutsRef.current.set(id, timeout);
    }
  }, []);

  const removeToast = useCallback((id: string) => {
    const timeout = timeoutsRef.current.get(id);
    if (timeout) {
      window.clearTimeout(timeout);
      timeoutsRef.current.delete(id);
    }
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const clearToasts = useCallback(() => {
    timeoutsRef.current.forEach(timeout => window.clearTimeout(timeout));
    timeoutsRef.current.clear();
    setToasts([]);
  }, []);

  // Cleanup timeouts on unmount
  useMemo(() => {
    if (typeof window !== 'undefined') {
      return () => {
        timeoutsRef.current.forEach(timeout => window.clearTimeout(timeout));
        timeoutsRef.current.clear();
      };
    }
    return () => {};
  }, []);

  const value = useMemo(() => ({
    toasts,
    addToast,
    removeToast,
    clearToasts,
  }), [toasts, addToast, removeToast, clearToasts]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div
        className="fixed bottom-4 right-4 z-[9999] flex flex-col gap-2 max-w-sm pointer-events-auto"
        role="region"
        aria-label="Notifications"
        aria-live="polite"
      >
        {toasts.map(toast => (
          <div
            key={toast.id}
            className={`flex items-start gap-3 bg-[#1a1a2e]/95 backdrop-blur-md ${BORDER_MAP[toast.type]} border rounded-xl px-4 py-3 shadow-2xl transition-all duration-300 hover:shadow-emerald-500/5`}
            role="alert"
          >
            {ICON_MAP[toast.type]}
            <p className="text-white text-sm flex-1 leading-relaxed">{toast.message}</p>
            <div className="flex items-center gap-1 shrink-0">
              {toast.action && (
                <button
                  onClick={toast.action.onClick}
                  className={`px-2 py-1 text-xs font-medium rounded-lg ${BG_MAP[toast.type]} text-white hover:opacity-80 transition-opacity`}
                >
                  {toast.action.label}
                </button>
              )}
              <button
                onClick={() => removeToast(toast.id)}
                className="text-white/30 hover:text-white/60 transition-colors p-0.5"
                aria-label="Dismiss notification"
              >
                <X size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (!context) throw new Error('useToast must be used within ToastProvider');
  return context;
}