import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';

interface AuthContextType {
  isAuthenticated: boolean;
  username: string;
  login: (username: string, password: string) => boolean;
  signup: (username: string, password: string) => boolean;
  guestLogin: () => void;
  logout: () => void;
  updateProfile: (data: Partial<ProfileData>) => void;
  hasUser: (username: string) => boolean;
}

interface ProfileData {
  displayName: string;
  avatar: string;
  joinDate: string;
  favorites?: string[];
  watchTime?: number;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const AUTH_KEY = 'stinkflix_auth';
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_DURATION = 30000; // 30 seconds

export function AuthProvider({ children }: { children: ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [username, setUsername] = useState('');
  const [profile, setProfile] = useState<ProfileData | null>(null);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [isLocked, setIsLocked] = useState(false);
  const [lockoutEnd, setLockoutEnd] = useState<number>(0);

  // Load auth state from localStorage
  useEffect(() => {
    try {
      const storedAuth = localStorage.getItem(AUTH_KEY);
      if (storedAuth) {
        const data = JSON.parse(storedAuth);
        setIsAuthenticated(data.isAuthenticated || false);
        setUsername(data.username || '');
        setProfile(data.profile || null);
      }
    } catch {
      localStorage.removeItem(AUTH_KEY);
    }
  }, []);

  // Check lockout status
  useEffect(() => {
    if (lockoutEnd > Date.now()) {
      setIsLocked(true);
      const timer = setTimeout(() => {
        setIsLocked(false);
        setLoginAttempts(0);
      }, lockoutEnd - Date.now());
      return () => clearTimeout(timer);
    } else {
      setIsLocked(false);
      setLoginAttempts(0);
    }
  }, [lockoutEnd]);

  const saveAuth = useCallback((user: string, profileData: ProfileData | null) => {
    try {
      localStorage.setItem(AUTH_KEY, JSON.stringify({
        isAuthenticated: true,
        username: user,
        profile: profileData,
      }));
    } catch {
      // Storage full or unavailable
    }
  }, []);

  const login = useCallback((user: string, pass: string): boolean => {
    if (isLocked) return false;

    try {
      const stored = localStorage.getItem(`stinkflix_user_${user}`);
      if (!stored) {
        const attempts = loginAttempts + 1;
        setLoginAttempts(attempts);
        if (attempts >= MAX_LOGIN_ATTEMPTS) {
          setLockoutEnd(Date.now() + LOCKOUT_DURATION);
        }
        return false;
      }

      const userData = JSON.parse(stored);
      if (userData.password !== pass) {
        const attempts = loginAttempts + 1;
        setLoginAttempts(attempts);
        if (attempts >= MAX_LOGIN_ATTEMPTS) {
          setLockoutEnd(Date.now() + LOCKOUT_DURATION);
        }
        return false;
      }

      setIsAuthenticated(true);
      setUsername(user);
      setProfile(userData.profile || {
        displayName: user,
        avatar: 'default',
        joinDate: userData.joinDate || new Date().toISOString(),
      });
      saveAuth(user, userData.profile || null);
      setLoginAttempts(0);
      return true;
    } catch {
      return false;
    }
  }, [isLocked, loginAttempts, saveAuth]);

  const signup = useCallback((user: string, pass: string): boolean => {
    if (isLocked) return false;
    if (typeof window === 'undefined') return false;

    try {
      if (localStorage.getItem(`stinkflix_user_${user}`)) return false;

      const profileData = {
        displayName: user,
        avatar: 'default',
        joinDate: new Date().toISOString(),
        favorites: [],
        watchTime: 0,
      };

      localStorage.setItem(`stinkflix_user_${user}`, JSON.stringify({
        password: pass,
        profile: profileData,
      }));

      setIsAuthenticated(true);
      setUsername(user);
      setProfile(profileData);
      saveAuth(user, profileData);
      return true;
    } catch {
      return false;
    }
  }, [isLocked, saveAuth]);

  const guestLogin = useCallback(() => {
    const guestName = `Guest_${Math.random().toString(36).substring(2, 6)}`;
    setIsAuthenticated(true);
    setUsername(guestName);
    const guestProfile: ProfileData = {
      displayName: 'Guest',
      avatar: 'default',
      joinDate: new Date().toISOString(),
      favorites: [],
      watchTime: 0,
    };
    setProfile(guestProfile);
    saveAuth(guestName, guestProfile);
  }, [saveAuth]);

  const logout = useCallback(() => {
    setIsAuthenticated(false);
    setUsername('');
    setProfile(null);
    setLoginAttempts(0);
    setIsLocked(false);
    setLockoutEnd(0);
    localStorage.removeItem(AUTH_KEY);
  }, []);

  const updateProfile = useCallback((data: Partial<ProfileData>) => {
    if (!username) return;
    const newProfile = { ...profile, ...data };
    setProfile(newProfile);
    saveAuth(username, newProfile);
    try {
      const existing = localStorage.getItem(`stinkflix_user_${username}`);
      if (existing) {
        const userData = JSON.parse(existing);
        userData.profile = newProfile;
        localStorage.setItem(`stinkflix_user_${username}`, JSON.stringify(userData));
      }
    } catch {
      // Ignore storage errors
    }
  }, [username, profile, saveAuth]);

  const hasUser = useCallback((user: string): boolean => {
    try {
      return localStorage.getItem(`stinkflix_user_${user}`) !== null;
    } catch {
      return false;
    }
  }, []);

  return (
    <AuthContext.Provider
      value={{
        isAuthenticated,
        username,
        login,
        signup,
        guestLogin,
        logout,
        updateProfile,
        hasUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
}